CREATE OR REPLACE FUNCTION public.create_company_agent(target_company_id uuid, agent_email text, agent_password text, agent_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
DECLARE
  new_user_id uuid;
  encrypted_pw text;
BEGIN
  -- Check if user exists
  IF EXISTS (SELECT 1 FROM auth.users WHERE email = agent_email) THEN
    RAISE EXCEPTION 'User % already exists.', agent_email;
  END IF;

  new_user_id := gen_random_uuid();
  encrypted_pw := crypt(agent_password, gen_salt('bf'));

  -- Create Auth User
  INSERT INTO auth.users (
    id, email, encrypted_password, email_confirmed_at, role, aud, created_at, updated_at,
    raw_user_meta_data
  )
  VALUES (
    new_user_id, agent_email, encrypted_pw, now(), 'authenticated', 'authenticated', now(), now(),
    jsonb_build_object(
        'full_name', agent_name, 
        'skip_profile_creation', 'true',
        'role', 'agent' -- <--- ADDED: Ensures Login.jsx routes to Agent Dashboard
    )
  );

  -- Create Identity (Already present, keeping it)
  INSERT INTO auth.identities (
    id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at, email
  )
  VALUES (
    gen_random_uuid(), new_user_id, jsonb_build_object('sub', new_user_id, 'email', agent_email),
    'email', NULL, now(), now(), agent_email
  );

  -- Create Profile Link
  INSERT INTO public.company_user_profiles (
    id, 
    company_id, 
    full_name, 
    role,
    email -- <--- Best practice to populate this for easy reading
  )
  VALUES (
    new_user_id, 
    target_company_id, 
    agent_name, 
    'agent', -- Standardized role name
    agent_email
  );

  RETURN new_user_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.find_clients_by_ssn(p_ssn text)
 RETURNS TABLE(id uuid, full_name text, masked_ssn text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  clean  text;
  pepper text;
  hash   text;
begin
  if p_ssn is null then return; end if;
  clean := regexp_replace(p_ssn, '\D', '', 'g');
  if length(clean) <> 9 then return; end if;

  select value into pepper from public.app_secrets where key = 'ssn_pepper' limit 1;
  if coalesce(pepper,'') = '' then return; end if;

  hash := encode(digest(pepper || clean, 'sha256'), 'hex');

  return query
  select c.id, c.full_name, c.ssn as masked_ssn, c.created_at
    from public.clients c
    join public.client_sensitive s on s.client_id = c.id
   where s.ssn_hash = hash;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_docs_reminders_cleanup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.docs_reminders r where r.client_id = new.client_id) then
    return new;
  end if;

  if new.bureau is null then
    delete from public.docs_reminders where client_id = new.client_id;
    return new;
  end if;

  update public.docs_reminders r
     set bureaus = array(
       select e from unnest(coalesce(r.bureaus, '{}'::text[])) e
       except
       select e2 from unnest(new.bureau) e2
     )
   where r.client_id = new.client_id;

  delete from public.docs_reminders
   where client_id = new.client_id
     and (bureaus is null or coalesce(array_length(bureaus, 1), 0) = 0);

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_set_affiliate_commission()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  rate numeric;
BEGIN
  IF NEW.affiliate_id IS NULL OR NEW.total_fee IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT commission_rate INTO rate
  FROM public.affiliates
  WHERE id = NEW.affiliate_id;

  IF rate IS NULL THEN
    rate := 0;
  END IF;

  NEW.affiliate_commission_amount := NEW.total_fee * rate;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.force_uppercase_name()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.full_name := UPPER(NEW.full_name);
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_client_ssn_full(p_client_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_uid      uuid := auth.uid();
  enc_key    text;
  enc_val    bytea;
  ssn_plain  text;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if not public.is_privileged() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select value into enc_key from public.app_secrets where key='ssn_enc_key' limit 1;
  if coalesce(enc_key,'')='' then
    raise exception 'secrets not configured';
  end if;

  select s.ssn_enc into enc_val
  from public.client_sensitive s
  where s.client_id = p_client_id;

  if enc_val is null then
    return null;
  end if;

  -- Decrypt; two-arg variant matches our encrypt call
  ssn_plain := pgp_sym_decrypt(enc_val, enc_key);

  return ssn_plain; -- 9 digits (no dashes)
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_paid_client()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  if new.is_paid = true and old.is_paid = false then
    insert into public.document_routing (client_id, round_count)
    values (new.id, 1);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user_signup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  meta_role text;
  meta_signup_type text;
BEGIN
  meta_role := new.raw_user_meta_data->>'role';
  meta_signup_type := new.raw_user_meta_data->>'signup_type';

  -- 🛑 SEPARATION GUARD:
  -- Your Login.jsx handles the inserts for these types manually.
  -- We must EXIT here so the database doesn't try to auto-create a Company.
  IF meta_role IN ('individual', 'client', 'affiliate', 'company', 'company_admin', 'agent') 
      OR meta_signup_type IN ('individual', 'affiliate', 'company') THEN
      RETURN new;
  END IF;

  -- ⬇️ LEGACY LOGIC BELOW (Runs only for manual Admin invites without specific roles)
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_calls_to_docs(p_call_task_id uuid, p_client_id uuid, p_is_fully_done boolean)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_next_round INTEGER;
BEGIN
    -- 1. Close the Call Task
    UPDATE call_routing SET status = 'COMPLETED' WHERE id = p_call_task_id;

    -- 2. If they are fully done, stop here.
    IF p_is_fully_done THEN
        RETURN 0;
    END IF;

    -- 3. If NOT done, calculate next round and insert new Doc Task
    SELECT COALESCE(MAX(round_count), 0) + 1 INTO v_next_round
    FROM document_routing
    WHERE client_id = p_client_id;

    INSERT INTO document_routing (client_id, round_count, status, assigned_admin_id)
    VALUES (p_client_id, v_next_round, 'PENDING', NULL);

    RETURN v_next_round; -- Return the new round number to the frontend
END;
$function$

CREATE OR REPLACE FUNCTION public.process_calls_to_docs(p_call_task_id uuid, p_client_id uuid, p_is_fully_done boolean, p_doc_admin_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_next_round INTEGER;
BEGIN
    -- 1. Close the Call Task
    UPDATE call_routing SET status = 'COMPLETED' WHERE id = p_call_task_id;

    -- 2. If they are fully done, stop here.
    IF p_is_fully_done THEN
        RETURN 0;
    END IF;

    -- 3. If NOT done, calc next round and assign to Doc Admin
    SELECT COALESCE(MAX(round_count), 0) + 1 INTO v_next_round
    FROM document_routing
    WHERE client_id = p_client_id;

    INSERT INTO document_routing (client_id, round_count, status, assigned_admin_id)
    VALUES (p_client_id, v_next_round, 'PENDING', p_doc_admin_id);

    RETURN v_next_round; 
END;
$function$

CREATE OR REPLACE FUNCTION public.update_client_completion_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  is_exp_done BOOLEAN;
  is_tu_done BOOLEAN;
  is_eq_done BOOLEAN;
  today TIMESTAMP WITH TIME ZONE := now();
BEGIN
  is_exp_done := COALESCE(NEW.exp_completed, FALSE) OR COALESCE(NEW.exp_na, FALSE);
  is_tu_done  := COALESCE(NEW.tu_completed, FALSE)  OR COALESCE(NEW.tu_na, FALSE);
  is_eq_done  := COALESCE(NEW.eq_completed, FALSE)  OR COALESCE(NEW.eq_na, FALSE);

  IF is_exp_done AND is_tu_done AND is_eq_done AND NEW.is_paid THEN
    IF NEW.date_completed IS NULL THEN
      NEW.date_completed := today;
    END IF;
    NEW.all_completed := TRUE;
  ELSE
    NEW.all_completed := FALSE;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
   NEW.updated_at = NOW();
   RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_weekly_payroll_summary()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  rec record;
  i int;
  login_time time;
  logout_time time;
  total_seconds int;
  emp_rate numeric;
  week_start_date date;
  week_end_date date;
begin
  -- Clear existing summary if needed (optional)
  -- delete from payroll_summary;

  for rec in
    select id, employee_id, log_date, login_times, logout_times
    from employee_logs
  loop
    total_seconds := 0;

    -- Make sure both arrays are not null
    if rec.login_times is not null and rec.logout_times is not null then
      for i in 0 .. LEAST(
        jsonb_array_length(rec.login_times),
        jsonb_array_length(rec.logout_times)
      ) - 1
      loop
        begin
          login_time := (rec.login_times ->> i)::time;
          logout_time := (rec.logout_times ->> i)::time;

          -- Add to total only if logout is after login
          if logout_time > login_time then
            total_seconds := total_seconds + extract(epoch from (logout_time - login_time));
          end if;
        exception
          when others then
            -- Skip bad pairs
            continue;
        end;
      end loop;
    end if;

    -- Skip logs with no valid session
    if total_seconds = 0 then
      continue;
    end if;

    -- Get rate from profiles
    select coalesce(rate_per_hour, 0) into emp_rate from profiles where id = rec.employee_id;

    -- Week starts on Saturday
    week_start_date := rec.log_date - ((extract(dow from rec.log_date)::int + 1) % 7);
    week_end_date := week_start_date + interval '6 days';

    -- Insert or update
    insert into payroll_summary (
      id, employee_id, week_start, week_end,
      total_hours, rate_per_hour, total_pay
    )
    values (
      gen_random_uuid(),
      rec.employee_id,
      week_start_date,
      week_end_date,
      round(total_seconds / 3600.0, 2),
      round(emp_rate, 2),
      round((total_seconds / 3600.0) * emp_rate, 2)
    )
    on conflict (employee_id, week_start)
    do update set
      total_hours = payroll_summary.total_hours + excluded.total_hours,
      total_pay = payroll_summary.total_pay + excluded.total_pay;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.upsert_client_ssn(p_client_id uuid, p_ssn text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  clean  text;
  last4  text;
  pepper text;
  hash   text;
begin
  if p_client_id is null or p_ssn is null then
    return jsonb_build_object('success', false, 'error', 'client_id and ssn required');
  end if;

  -- Accept "xxx-xx-xxxx" or digits; require exactly 9 digits.
  clean := regexp_replace(p_ssn, '\D', '', 'g');
  if length(clean) <> 9 then
    return jsonb_build_object('success', false, 'error', 'invalid ssn (need 9 digits)');
  end if;

  last4 := right(clean, 4);

  select value into pepper from public.app_secrets where key = 'ssn_pepper' limit 1;
  if coalesce(pepper, '') = '' then
    return jsonb_build_object('success', false, 'error', 'pepper not configured');
  end if;

  hash := encode(digest(pepper || clean, 'sha256'), 'hex');

  insert into public.client_sensitive (client_id, ssn_last4, ssn_hash)
  values (p_client_id, last4, hash)
  on conflict (client_id) do update
    set ssn_last4 = excluded.ssn_last4,
        ssn_hash  = excluded.ssn_hash;

  -- Mask what’s in the public table so UI can display safely.
  update public.clients
     set ssn = '***-**-' || last4
   where id = p_client_id;

  return jsonb_build_object('success', true, 'last4', last4);
end;
$function$

CREATE OR REPLACE FUNCTION public.upsert_client_ssn_full(p_client_id uuid, p_ssn text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  clean     text;
  last4     text;
  pepper    text;
  enc_key   text;
  hash_hex  text;
  enc_ssn   bytea;
  v_uid     uuid := auth.uid();
begin
  if v_uid is null then
    return jsonb_build_object('success', false, 'error', 'not authenticated');
  end if;
  if not public.is_privileged() then
    return jsonb_build_object('success', false, 'error', 'forbidden');
  end if;

  if p_client_id is null or p_ssn is null then
    return jsonb_build_object('success', false, 'error', 'client_id and ssn required');
  end if;

  clean := regexp_replace(p_ssn, '\D', '', 'g');
  if length(clean) <> 9 then
    return jsonb_build_object('success', false, 'error', 'invalid ssn (need 9 digits)');
  end if;

  last4 := right(clean, 4);

  select value into pepper  from public.app_secrets where key='ssn_pepper'  limit 1;
  select value into enc_key from public.app_secrets where key='ssn_enc_key' limit 1;
  if coalesce(pepper,'')='' or coalesce(enc_key,'')='' then
    return jsonb_build_object('success', false, 'error', 'secrets not configured');
  end if;

  hash_hex := encode(digest(pepper || clean, 'sha256'), 'hex');

  -- encryption via pgcrypto (extensions schema now in search_path)
  enc_ssn  := pgp_sym_encrypt(clean, enc_key, 'compress-algo=1,cipher-algo=aes256');

  insert into public.client_sensitive (client_id, ssn_last4, ssn_hash, ssn_enc)
  values (p_client_id, last4, hash_hex, enc_ssn)
  on conflict (client_id) do update
    set ssn_last4 = excluded.ssn_last4,
        ssn_hash  = excluded.ssn_hash,
        ssn_enc   = excluded.ssn_enc;

  update public.clients
     set ssn = '***-**-' || last4
   where id = p_client_id;

  return jsonb_build_object('success', true, 'last4', last4);
end;
$function$

CREATE OR REPLACE FUNCTION public.verify_client_ssn(p_client_id uuid, p_ssn text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  clean  text; 
  pepper text; 
  hash   text;
begin
  if p_client_id is null or p_ssn is null then return false; end if;
  clean := regexp_replace(p_ssn, '\D', '', 'g');
  if length(clean) <> 9 then return false; end if;

  select value into pepper from public.app_secrets where key='ssn_pepper' limit 1;
  if coalesce(pepper,'') = '' then return false; end if;

  hash := encode(digest(pepper || clean, 'sha256'), 'hex');

  return exists(
    select 1 from public.client_sensitive s 
     where s.client_id = p_client_id and s.ssn_hash = hash
  );
end;
$function$
